fulfill.run:
const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const STORAGE_KEY = 'devtool_swimlane'
$self.state = $observable({ enabled: true, showTag: true, activeSwimlaneId: '', list: [] })
$self.loadSwimlane = async () => {
  try {
    const res = await $chrome.storage.local.get(STORAGE_KEY)
    const s = res[STORAGE_KEY] || { enabled: true, showTag: true, activeSwimlaneId: '', swimlanes: [] }
    $self.state.enabled = s.enabled
    $self.state.showTag = s.showTag
    $self.state.activeSwimlaneId = s.activeSwimlaneId
    $self.state.list = s.swimlanes || []
  } catch (e) {
    $logger.error('加载泳道配置失败', e)
    $message.error('加载泳道配置失败')
  }
}
$self.saveSwimlane = async (s) => {
  await $chrome.storage.local.set({ [STORAGE_KEY]: { enabled: s.enabled, showTag: s.showTag, activeSwimlaneId: s.activeSwimlaneId, swimlanes: JSON.parse(JSON.stringify(s.list || [])) } })
}
$self.showAddOrUpdateDialog = (row) => {
  const dialog = $self.query(re + '.editDialog').take()
  if (dialog) {
    dialog.value = row ? { ...row } : {}
    dialog.setComponentProps({ open: true, title: row ? '编辑泳道' : '新增泳道' })
  }
}
$self.handleActivate = async (id) => {
  const newId = $self.state.activeSwimlaneId === id ? '' : id
  $self.state.activeSwimlaneId = newId
  try {
    await $self.saveSwimlane($self.state)
    $message.success(newId ? '泳道已激活' : '已取消激活泳道')
  } catch (e) {
    $message.error('操作失败')
  }
}
$self.handleDelete = async (id) => {
  $self.state.list = $self.state.list.filter((i) => i.id !== id)
  if ($self.state.activeSwimlaneId === id) $self.state.activeSwimlaneId = ''
  try {
    await $self.saveSwimlane($self.state)
    $message.success('泳道已删除')
  } catch (e) {
    $message.error('删除失败')
  }
}
$effect(() => { $self.loadSwimlane() }, [])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => { $self.value = rf.state.enabled }, [rf.state.enabled])
$props({
  onChange: (checked) => {
    rf.state.enabled = checked
    rf.saveSwimlane(rf.state).then(() => $message.success(checked ? '泳道已开启' : '泳道已关闭'))
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => { $self.value = rf.state.showTag }, [rf.state.showTag])
$props({
  onChange: (checked) => {
    rf.state.showTag = checked
    rf.saveSwimlane(rf.state).then(() => $message.success(checked ? '泳道角标已开启' : '泳道角标已关闭'))
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const en = rf.state.enabled
  const id = rf.state.activeSwimlaneId
  const item = (rf.state.list || []).find((s) => s.id === id)
  $self.value = (en && id) ? ('当前泳道：' + (item ? item.value : '—')) : ''
  $self.display = (en && id) ? 'visible' : 'none'
}, [rf.state.enabled, rf.state.activeSwimlaneId, rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const en = rf.state.enabled
  const id = rf.state.activeSwimlaneId
  const show = en && !id
  $self.value = show ? '当前走主干（无激活泳道）' : ''
  $self.display = show ? 'visible' : 'none'
}, [rf.state.enabled, rf.state.activeSwimlaneId])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const show = !rf.state.enabled
  $self.value = show ? '泳道已关闭，全部走主干' : ''
  $self.display = show ? 'visible' : 'none'
}, [rf.state.enabled])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => rf.showAddOrUpdateDialog(null) })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const isActive = !!(row && rf.state.activeSwimlaneId === row.id)
  $self.value = row ? row.name : ''
  $props({ strong: isActive })
}, [rf.state.activeSwimlaneId, rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const isActive = !!(row && rf.state.activeSwimlaneId === row.id)
  $self.value = isActive ? '激活中' : ''
  $self.display = isActive ? 'visible' : 'none'
}, [rf.state.activeSwimlaneId, rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $self.value = row ? row.value : ''
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const isActive = !!(row && rf.state.activeSwimlaneId === row.id)
  const dis = !rf.state.enabled
  $props({
    children: isActive ? '取消激活' : '激活',
    icon: isActive ? 'MinusCircleOutlined' : 'CheckCircleOutlined',
    type: isActive ? 'default' : 'primary',
    disabled: dis,
    onClick: () => { if (row) rf.handleActivate(row.id) },
  })
}, [rf.state.activeSwimlaneId, rf.state.enabled, rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); rf.showAddOrUpdateDialog(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onConfirm: async () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); await rf.handleDelete(row.id) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('swimlaneSettingsDiv') + 'swimlaneSettingsDiv'.length)
const rf = $self.query(re).take()
$props({
  onCancel: () => { $self.componentProps.open = false },
  onOk: () => {
    $self.validate().then(async () => {
      const form = $self.value
      const exists = rf.state.list.some((d) => d.value === form.value && d.id !== form.id)
      if (exists) {
        const vField = $self.query($self.address.entire + '.value').take()
        if (vField) vField.setFeedback({ type: 'error', messages: ['该泳道值已存在，请使用不同的值'] })
        return
      }
      const list = rf.state.list.slice()
      if (form.id) {
        const idx = list.findIndex((i) => i.id === form.id)
        if (idx >= 0) list[idx] = { id: form.id, name: form.name, value: form.value }
        rf.state.list = list
        await rf.saveSwimlane(rf.state)
        $message.success('泳道已更新')
      } else {
        const created = { id: 'swimlane_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7), name: form.name, value: form.value }
        list.push(created)
        rf.state.list = list
        await rf.saveSwimlane(rf.state)
        $message.success('泳道已新增')
      }
      $self.componentProps.open = false
    }).catch((e) => $logger.info('校验失败', e))
  },
})
